const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
const hour = new Date().getHours();
const slot = hour < 15 ? 'morning' : 'evening';

const calendar = JSON.parse($input.item.json.calendar);
const dayData = calendar.days.find(d => d.date === today);
const post = dayData?.posts.find(p => p.slot === slot);

return { post };

const tracker = JSON.parse($input.item.json.tracker);
const post = $node['Get Calendar Entry'].json.post;

tracker.posts.push({
  post_id: post.post_id,
  date: new Date().toISOString(),
  platform: 'TikTok',
  hook: post.hook,
  tiktok_url: $node['Upload to TikTok'].json.share_url,
  instagram_url: $node['Publish Reels'].json.permalink,
  metrics_24h: { views: 0, likes: 0, comments: 0, shares: 0, saves: 0 }
});

return { tracker };

